      hu: ["A Női Nemzeti Tanács irányítja", "Pandánuszlevél termékeket árul", "A repülőtér közelében található", "Támogatja a helyi kézműveseket"],
      ro: ["Administrat de Consiliul Femeilor", "Vinde produse din frunze de pandanus", "Situat lângă aeroport", "Sprijină artizanii locali"],
      en: ["Run by Tuvalu National Council of Women", "Features pandanus leaf products", "Located near the main airport", "Supports local island artisans"],
      es: ["Dirigido por el Consejo de Mujeres", "Vende productos de hoja de pandano", "Situado cerca del aeropuerto", "Apoya a los artesanos locales"],
      pt: ["Gerido pelo Conselho de Mulheres", "Vende produtos de folha de pandano", "Situado perto do aeroporto", "Apoia os artesãos locais"],
